module benchmark/solution

import std/list (length, take, drop)

pure func merge(xs: [int], ys: [int]) -> [int] =
  match xs {
    [] => ys,
    x :: restX => match ys {
      [] => xs,
      y :: restY =>
        if x <= y then x :: merge(restX, ys)
        else y :: merge(xs, restY)
    }
  }

pure func split(xs: [int]) -> ([int], [int]) {
  let midpoint = length(xs) / 2;
  (take(midpoint, xs), drop(midpoint, xs))
}

pure func mergeSort(xs: [int]) -> [int] =
  if length(xs) <= 1 then xs
  else match split(xs) {
    (left, right) => merge(mergeSort(left), mergeSort(right))
  }

export func main() -> () ! {IO} {
  println(show(mergeSort([38, 27, 43, 3, 9, 82, 10])))
}
